-- =====================================================================
--  FARMA - Base de datos completa 
--  Un solo script: crea la base, las tablas, los 500 productos, el administrador
--  y 182 ventas de ejemplo para los reportes.
--
--  CÓMO USARLO EN MySQL Workbench:
--    1. File  ->  Open SQL Script...  y abre este archivo.
--    2. Ejecuta TODO con el rayo (⚡) o con Ctrl+Shift+Enter (sin seleccionar nada).
--    3. Al final deben salir 500 productos, 1 usuario (el admin) y 182 ventas.
--
--  ¡OJO! Si ya existe "farma_db", este script la BORRA y la vuelve a crear desde
--  cero (se pierden los productos, usuarios y ventas que hayas agregado).
--  Ya incluye las columnas de pago de Culqi: no hace falta ninguna migración.
--
--  USUARIO ADMINISTRADOR:
--    correo: admin@farma.com    contraseña: admin12345
--    (los clientes se crean desde la web, en el botón "Registrarse")
-- =====================================================================

SET NAMES utf8mb4;   -- para que las tildes y la ñ se guarden bien desde cualquier cliente

DROP DATABASE IF EXISTS `farma_db`;

CREATE DATABASE IF NOT EXISTS `farma_db`
  DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `farma_db`;

-- ---------------------------------------------------------------------
-- Tabla PRODUCTOS (ya incluye todas las columnas del Avance 2)
--   codigo            : código único para buscar/editar (FAR-0001...)
--   marca             : marca del producto
--   fecha_vencimiento : NULL en los equipos médicos (no vencen)
--   activo            : 1 = se muestra en la tienda, 0 = dado de baja (oculto)
--   descuento         : % de oferta (0 = sin oferta, de 5 a 90 = en oferta)
-- ---------------------------------------------------------------------
CREATE TABLE `productos` (
  `id_producto` int NOT NULL AUTO_INCREMENT,
  `codigo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `marca` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `precio` decimal(10,2) NOT NULL,
  `categoria` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `imagen_url` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `stock` int NOT NULL DEFAULT 0,
  `activo` bit(1) NOT NULL DEFAULT b'1',
  `fecha_vencimiento` date DEFAULT NULL,
  `descuento` int NOT NULL DEFAULT 0,
  `fecha_creacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_producto`),
  UNIQUE KEY `uk_productos_codigo` (`codigo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- Ofertas de ejemplo (Avance Final: descuento mínimo de 5%)
UPDATE `productos` SET `descuento` = 10 WHERE `codigo` = 'FAR-0003';
UPDATE `productos` SET `descuento` = 15 WHERE `codigo` = 'FAR-0011';
UPDATE `productos` SET `descuento` = 20 WHERE `codigo` = 'FAR-0014';
UPDATE `productos` SET `descuento` = 5  WHERE `codigo` = 'FAR-0015';
UPDATE `productos` SET `descuento` = 25 WHERE `codigo` = 'FAR-0016';
UPDATE `productos` SET `descuento` = 10 WHERE `codigo` = 'FAR-0020';

-- Catálogo ampliado: 480 productos más (FAR-0021 a FAR-0500), 500 en total.
-- Los que no tienen foto propia muestran la imagen genérica de la tienda.

-- ---------------------------------------------------------------------
-- Tabla USUARIOS
--   rol : ADMIN entra al panel; CLIENTE es un comprador normal.
--   La contraseña va cifrada con BCrypt (no se guarda en texto plano).
-- ---------------------------------------------------------------------
CREATE TABLE `usuarios` (
  `id_usuario` int NOT NULL AUTO_INCREMENT,
  `nombre` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `apellido` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `correo` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `contrasena` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `telefono` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rol` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'CLIENTE',
  `fecha_registro` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_usuario`),
  UNIQUE KEY `correo` (`correo`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- Tablas VENTAS y DETALLE_VENTA (Avance Final: carrito con boleta)
--   Cada compra del carrito es una venta con su boleta B001-00000001.
--   Los precios incluyen IGV: total = op_gravada + igv.
--   detalle_venta guarda una copia del producto (código, nombre, precio)
--   para que la boleta no cambie si luego se edita el producto.
-- ---------------------------------------------------------------------
CREATE TABLE `ventas` (
  `id_venta` int NOT NULL AUTO_INCREMENT,
  `numero` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipo_comprobante` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'BOLETA',
  `id_usuario` int DEFAULT NULL,
  `cliente_nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cliente_dni` varchar(8) COLLATE utf8mb4_unicode_ci NOT NULL,
  `cliente_correo` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `metodo_pago` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `pago_estado` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDIENTE',
  `pago_pasarela` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pago_referencia` varchar(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tarjeta_marca` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tarjeta_ultimos4` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `subtotal_sin_descuento` decimal(10,2) NOT NULL DEFAULT 0.00,
  `descuento_total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `op_gravada` decimal(10,2) NOT NULL DEFAULT 0.00,
  `igv` decimal(10,2) NOT NULL DEFAULT 0.00,
  `total` decimal(10,2) NOT NULL DEFAULT 0.00,
  `fecha` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_venta`),
  UNIQUE KEY `uk_ventas_numero` (`numero`),
  KEY `idx_ventas_fecha` (`fecha`),
  CONSTRAINT `fk_ventas_usuario` FOREIGN KEY (`id_usuario`) REFERENCES `usuarios` (`id_usuario`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `detalle_venta` (
  `id_detalle` int NOT NULL AUTO_INCREMENT,
  `id_venta` int NOT NULL,
  `id_producto` int NOT NULL,
  `codigo` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `nombre` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `categoria` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `cantidad` int NOT NULL,
  `precio_unitario` decimal(10,2) NOT NULL,
  `descuento` int NOT NULL DEFAULT 0,
  `precio_final` decimal(10,2) NOT NULL,
  `importe` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id_detalle`),
  KEY `idx_detalle_producto` (`id_producto`),
  CONSTRAINT `fk_detalle_venta` FOREIGN KEY (`id_venta`) REFERENCES `ventas` (`id_venta`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Ventas de ejemplo (junio a noviembre de 2026) para que los reportes muestren datos.
-- Las ofertas se aplican desde octubre. Los nombres y DNI son inventados.

-- ---------------------------------------------------------------------
-- Asignación de imágenes por código de producto (FAR-0001 a FAR-0500)
-- Cada producto tiene su propia imagen física asociada a su código único
-- ---------------------------------------------------------------------
UPDATE `productos` SET `imagen_url` = CONCAT('img/productos/', `codigo`, '.jpg');

-- ---------------------------------------------------------------------
-- Verificación
-- ---------------------------------------------------------------------
SELECT COUNT(*) AS total_productos FROM `productos`;                 -- debe ser 500
SELECT `categoria`, COUNT(*) AS productos FROM `productos` GROUP BY `categoria` ORDER BY productos DESC;
SELECT `id_usuario`,`nombre`,`correo`,`rol` FROM `usuarios`;         -- debe mostrar solo el admin
SELECT COUNT(*) AS total_ventas FROM `ventas`;                       -- ventas de ejemplo para los reportes
